interface InvoiceLine { units: number; price: number }
class InvoiceRollup {
  @State amount: number = 0
  recompute(lines: InvoiceLine[]): void {
    let subtotal: number = 0
    lines.forEach((line: InvoiceLine) => {
      subtotal += line.units * line.price
    })
    this.amount = subtotal
  }
}

