@Component
struct CaptionList {
  @State @Watch('refreshLabels') labels: string[] = []
  refreshLabels(): void { console.info('labels changed') }
  build() {
    Column() {
      ForEach(this.labels, (label: string) => {
        Text(label)
      })
    }
  }
}

